use anyhow::Result;
use futures_util::{SinkExt, StreamExt};
use std::sync::Arc;
use tokio::sync::{mpsc, Mutex};
use tokio_tungstenite::{connect_async, tungstenite::Message as WsMessage};
use tokio::time::Duration;

use crate::ai::parse_gateway_event;

#[derive(Debug, Clone)]
pub enum GatewayMessage {
    TextDelta { session_id: String, delta: String },
    TextDone { session_id: String },
    RunComplete {
        session_id: String,
        text: String,
        input_tokens: u64,
        output_tokens: u64,
        error: Option<String>,
    },
    Usage { input: u64, output: u64 },
    Connected,
    Disconnected,
    Reconnecting,
    Error(String),
}

pub struct GatewayConnection {
    url: String,
    sender: Option<mpsc::Sender<String>>,
    receiver: Option<mpsc::Receiver<GatewayMessage>>,
    connected: Arc<Mutex<bool>>,
    reconnect_tx: Option<mpsc::Sender<()>>,
}

impl GatewayConnection {
    pub fn new(url: &str) -> Self {
        Self {
            url: url.to_string(),
            sender: None,
            receiver: None,
            connected: Arc::new(Mutex::new(false)),
            reconnect_tx: None,
        }
    }

    pub fn take_receiver(&mut self) -> Option<mpsc::Receiver<GatewayMessage>> {
        self.receiver.take()
    }

    pub fn is_connected(&self) -> bool {
        true
    }

    pub async fn connect(&mut self) -> Result<()> {
        let (ws_stream, _) = connect_async(&self.url).await?;
        let (write, mut read) = ws_stream.split();

        let (outgoing_tx, mut outgoing_rx) = mpsc::channel::<String>(32);
        let (incoming_tx, incoming_rx) = mpsc::channel::<GatewayMessage>(64);
        let (reconnect_tx, mut reconnect_rx) = mpsc::channel::<()>(1);

        self.sender = Some(outgoing_tx);
        self.receiver = Some(incoming_rx);
        self.reconnect_tx = Some(reconnect_tx);

        {
            let mut c = self.connected.lock().await;
            *c = true;
        }

        let connected = self.connected.clone();
        let connected_clone = connected.clone();
        let url = self.url.clone();
        let incoming_tx_clone = incoming_tx.clone();

        tokio::spawn(async move {
            let mut write = write;
            while let Some(msg) = outgoing_rx.recv().await {
                if write.send(WsMessage::Text(msg.into())).await.is_err() {
                    break;
                }
            }
        });

        tokio::spawn(async move {
            loop {
                tokio::select! {
                    _ = reconnect_rx.recv() => {
                        break;
                    }
                    msg = read.next() => {
                        match msg {
                            Some(Ok(WsMessage::Text(text))) => {
                                if let Some(event) = parse_gateway_event(&text) {
                                    let gateway_msg = match event {
                                        crate::ai::GatewayEvent::AgentTextDelta { session_id, delta } => {
                                            Some(GatewayMessage::TextDelta { session_id, delta })
                                        }
                                        crate::ai::GatewayEvent::AgentTextDone { session_id } => {
                                            Some(GatewayMessage::TextDone { session_id })
                                        }
                                        crate::ai::GatewayEvent::AgentRunComplete {
                                            session_id,
                                            result,
                                            error,
                                            ..
                                        } => {
                                            let (text, input_tokens, output_tokens) = result
                                                .map(|r| {
                                                    let t = r
                                                        .payloads
                                                        .first()
                                                        .and_then(|p| p.text.clone())
                                                        .unwrap_or_default();
                                                    let (i, o) = r
                                                        .meta
                                                        .and_then(|m| m.usage)
                                                        .map(|u| (u.input, u.output))
                                                        .unwrap_or((0, 0));
                                                    (t, i, o)
                                                })
                                                .unwrap_or_default();
                                            Some(GatewayMessage::RunComplete {
                                                session_id,
                                                text,
                                                input_tokens,
                                                output_tokens,
                                                error,
                                            })
                                        }
                                        crate::ai::GatewayEvent::AgentUsage {
                                            input, output, ..
                                        } => Some(GatewayMessage::Usage { input, output }),
                                        crate::ai::GatewayEvent::Error { message, .. } => {
                                            Some(GatewayMessage::Error(message))
                                        }
                                        _ => None,
                                    };
                                    if let Some(gm) = gateway_msg {
                                        if incoming_tx.send(gm).await.is_err() {
                                            break;
                                        }
                                    }
                                }
                            }
                            Some(Ok(WsMessage::Close(_))) | None => {
                                let mut c = connected.lock().await;
                                *c = false;
                                let _ = incoming_tx.send(GatewayMessage::Disconnected).await;
                                break;
                            }
                            Some(Err(_)) => {
                                let mut c = connected.lock().await;
                                *c = false;
                                let _ = incoming_tx.send(GatewayMessage::Disconnected).await;
                                break;
                            }
                            _ => {}
                        }
                    }
                }
            }
        });

        Ok(())
    }

    pub async fn reconnect(&mut self) -> Result<()> {
        self.close().await;
        tokio::time::sleep(Duration::from_millis(100)).await;
        self.connect().await
    }

    pub async fn send(&self, request: &crate::ai::AgentRequest) -> Result<()> {
        if let Some(sender) = &self.sender {
            let json = serde_json::to_string(request)?;
            sender.send(json).await?;
        }
        Ok(())
    }

    pub async fn close(&mut self) {
        if let Some(tx) = &self.reconnect_tx {
            let _ = tx.send(()).await;
        }
        self.sender = None;
        self.receiver = None;
        self.reconnect_tx = None;
        let mut c = self.connected.lock().await;
        *c = false;
    }
}

pub async fn start_reconnect_loop(
    gateway: Arc<Mutex<GatewayConnection>>,
    msg_tx: mpsc::Sender<GatewayMessage>,
) {
    let base_backoff = Duration::from_secs(5);
    let max_backoff = Duration::from_secs(60);
    let mut backoff = base_backoff;

    loop {
        tokio::time::sleep(backoff).await;

        let should_reconnect = {
            let g = gateway.lock().await;
            !g.is_connected()
        };

        if should_reconnect {
            let _ = msg_tx.send(GatewayMessage::Reconnecting).await;

            let result = {
                let mut g = gateway.lock().await;
                g.reconnect().await
            };

            match result {
                Ok(_) => {
                    let _ = msg_tx.send(GatewayMessage::Connected).await;
                    backoff = base_backoff; // reset on success
                }
                Err(_) => {
                    let _ = msg_tx.send(GatewayMessage::Disconnected).await;
                    // exponential backoff with cap
                    backoff = (backoff * 2).min(max_backoff);
                }
            }
        } else {
            // Reset backoff if connected (in case it was increased earlier)
            backoff = base_backoff;
        }
    }
}

