use anyhow::Result;
use futures_util::{SinkExt, StreamExt};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::Arc;
use tokio::sync::{mpsc, Mutex};
use tokio::time::{Duration, Instant};
use tokio_tungstenite::{connect_async, tungstenite::Message as WsMessage};

use crate::ai::parse_gateway_event;

// Protocol constants
const PROTOCOL_VERSION: u32 = 3;

// Protocol structs
#[derive(Debug, Clone, Serialize)]
struct ConnectParams {
    #[serde(rename = "minProtocol")]
    min_protocol: u32,
    #[serde(rename = "maxProtocol")]
    max_protocol: u32,
    client: ClientInfo,
    role: String,
    scopes: Vec<String>,
    caps: Vec<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    commands: Option<Vec<String>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    device: Option<DeviceInfo>,
    #[serde(skip_serializing_if = "Option::is_none")]
    auth: Option<AuthInfo>,
    #[serde(skip_serializing_if = "Option::is_none")]
    permissions: Option<serde_json::Value>,
    #[serde(rename = "pathEnv", skip_serializing_if = "Option::is_none")]
    path_env: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
struct ClientInfo {
    id: String,
    version: String,
    platform: String,
    mode: String,
    #[serde(rename = "displayName", skip_serializing_if = "Option::is_none")]
    display_name: Option<String>,
    #[serde(rename = "instanceId", skip_serializing_if = "Option::is_none")]
    instance_id: Option<String>,
}

#[derive(Debug, Clone, Serialize)]
struct DeviceInfo {
    id: String,
    public_key: String,
    signature: String,
    signed_at: u64,
    nonce: String,
}

#[derive(Debug, Clone, Serialize)]
struct AuthInfo {
    token: Option<String>,
    device_token: Option<String>,
    password: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
struct HelloOkPayload {
    #[serde(rename = "type")]
    payload_type: String,
    server: ServerInfo,
    snapshot: serde_json::Value,
    auth: AuthResponse,
    policy: PolicyInfo,
    methods: Vec<String>,
    events: Vec<String>,
    caps: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
struct ServerInfo {
    version: String,
}

#[derive(Debug, Clone, Deserialize)]
struct AuthResponse {
    #[serde(rename = "deviceToken")]
    device_token: String,
    role: String,
    scopes: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
struct PolicyInfo {
    #[serde(rename = "tickIntervalMs")]
    tick_interval_ms: u64,
}

#[derive(Debug, Clone, Deserialize, Serialize)]
struct RequestFrame {
    #[serde(rename = "type")]
    frame_type: String,
    id: String,
    method: String,
    params: serde_json::Value,
}

#[derive(Debug, Clone, Deserialize)]
struct ResponseFrame {
    #[serde(rename = "type")]
    frame_type: String,
    id: String,
    ok: bool,
    payload: Option<serde_json::Value>,
    error: Option<ResponseError>,
}

#[derive(Debug, Clone, Deserialize)]
struct ResponseError {
    code: String,
    message: String,
    details: Option<serde_json::Value>,
}

#[derive(Debug, Clone, Deserialize)]
struct EventFrame {
    #[serde(rename = "type")]
    frame_type: String,
    event: String,
    seq: Option<u64>,
    payload: Option<serde_json::Value>,
}

pub enum GatewayMessage {
    TextDelta { session_id: String, delta: String },
    TextDone { session_id: String },
    RunComplete {
        session_id: String,
        text: String,
        input_tokens: u64,
        output_tokens: u64,
        error: Option<String>,
    },
    Usage { input: u64, output: u64 },
    Connected,
    Disconnected,
    Reconnecting,
    Error(String),
}

pub struct GatewayConnection {
    url: String,
    token: Option<String>,
    sender: Option<mpsc::Sender<String>>,
    receiver: Option<mpsc::Receiver<GatewayMessage>>,
    connected: Arc<Mutex<bool>>,
    reconnect_tx: Option<mpsc::Sender<()>>,
    // Protocol state
    device_token: Arc<Mutex<Option<String>>>,
    pending_requests: Arc<Mutex<std::collections::HashMap<String, mpsc::Sender<Result<serde_json::Value, anyhow::Error>>>>>,
    tick_interval_ms: Arc<Mutex<Option<u64>>>,
    last_event_seq: Arc<Mutex<u64>>,
    last_tick: Arc<Mutex<Instant>>,
}

impl GatewayConnection {
    pub fn new(url: &str, token: Option<String>) -> Self {
        Self {
            url: url.to_string(),
            token,
            sender: None,
            receiver: None,
            connected: Arc::new(Mutex::new(false)),
            reconnect_tx: None,
            device_token: Arc::new(Mutex::new(None)),
            pending_requests: Arc::new(Mutex::new(std::collections::HashMap::new())),
            tick_interval_ms: Arc::new(Mutex::new(None)),
            last_event_seq: Arc::new(Mutex::new(0)),
            last_tick: Arc::new(Mutex::new(Instant::now())),
        }
    }

    pub fn take_receiver(&mut self) -> Option<mpsc::Receiver<GatewayMessage>> {
        self.receiver.take()
    }

    pub async fn is_connected(&self) -> bool {
        *self.connected.lock().await
    }

    pub async fn connect(&mut self) -> Result<()> {
        // Connect to WebSocket
        let (ws_stream, _) = connect_async(&self.url).await?;
        let (mut write, mut read) = ws_stream.split();

        // Channels
        let (outgoing_tx, mut outgoing_rx) = mpsc::channel::<String>(32);
        let (incoming_tx, incoming_rx) = mpsc::channel::<GatewayMessage>(64);
        let (reconnect_tx, mut reconnect_rx) = mpsc::channel(1);
        let (handshake_tx, mut handshake_rx) = mpsc::channel(1);

        self.sender = Some(outgoing_tx.clone());
        self.receiver = Some(incoming_rx);
        self.reconnect_tx = Some(reconnect_tx);

        // Initially not connected
        {
            let mut c = self.connected.lock().await;
            *c = false;
        }

        // Clone shared state for reader task (these will be moved into the task)
        let base_token = self.token.clone();
        let connected_task = self.connected.clone();
        let device_token_task = self.device_token.clone();
        let pending_requests_task = self.pending_requests.clone();
        let tick_interval_ms_task = self.tick_interval_ms.clone();
        let last_event_seq_task = self.last_event_seq.clone();
        let last_tick_task = self.last_tick.clone();
        let incoming_tx_task = incoming_tx.clone();

        // Spawn writer task
        tokio::spawn(async move {
            while let Some(msg) = outgoing_rx.recv().await {
                if write.send(WsMessage::Text(msg.into())).await.is_err() {
                    break;
                }
            }
        });

        // Spawn reader task
        tokio::spawn(async move {
            let mut handshake_completed = false;
            let mut connect_req_id = String::new();

            loop {
                tokio::select! {
                    _ = reconnect_rx.recv() => {
                        break;
                    }
                    msg = read.next() => {
                        match msg {
                            Some(Ok(WsMessage::Text(text))) => {
                                // Try EventFrame first (server push)
                                if let Ok(event) = serde_json::from_str::<EventFrame>(&text) {
                                    // Handle connect.challenge during handshake
                                    if !handshake_completed && event.event == "connect.challenge" {
                                        // Extract nonce from payload
                                        let nonce = match &event.payload {
                                            Some(p) => p["nonce"].as_str(),
                                            None => None,
                                        };
                                        let nonce = match nonce {
                                            Some(n) => n,
                                            None => {
                                                let _ = incoming_tx_task.send(GatewayMessage::Error("Missing nonce in challenge".to_string())).await;
                                                break;
                                            }
                                        };

                                        // Build connect request
                                        let req_id = uuid::Uuid::new_v4().to_string();
                                        connect_req_id = req_id.clone();

                                        // Determine auth token: prefer explicit token, else stored device token
                                        let token_opt = {
                                            if let Some(ref t) = base_token {
                                                Some(t.clone())
                                            } else {
                                                let stored = device_token_task.lock().await;
                                                stored.clone()
                                            }
                                        };

                                        let auth = if let Some(t) = token_opt {
                                            Some(AuthInfo {
                                                token: Some(t),
                                                device_token: None,
                                                password: None,
                                            })
                                        } else {
                                            None
                                        };

                                        let connect_params = ConnectParams {
                                            min_protocol: PROTOCOL_VERSION,
                                            max_protocol: PROTOCOL_VERSION,
                                            client: ClientInfo {
                                                id: "ai-dashboard".to_string(),
                                                version: env!("CARGO_PKG_VERSION").to_string(),
                                                platform: std::env::consts::OS.to_string(),
                                                mode: "operator".to_string(),
                                                display_name: None,
                                                instance_id: None,
                                            },
                                            role: "operator".to_string(),
                                            scopes: vec!["operator.admin".to_string()],
                                            caps: vec![],
                                            commands: None,
                                            device: None,
                                            auth,
                                            permissions: None,
                                            path_env: None,
                                        };

                                        let params_value = match serde_json::to_value(connect_params) {
                                            Ok(v) => v,
                                            Err(e) => {
                                                let _ = incoming_tx_task.send(GatewayMessage::Error(format!("Serialization error: {}", e))).await;
                                                break;
                                            }
                                        };

                                        let req_frame = RequestFrame {
                                            frame_type: "req".to_string(),
                                            id: req_id,
                                            method: "connect".to_string(),
                                            params: params_value,
                                        };

                                        let json = match serde_json::to_string(&req_frame) {
                                            Ok(j) => j,
                                            Err(e) => {
                                                let _ = incoming_tx_task.send(GatewayMessage::Error(format!("JSON error: {}", e))).await;
                                                break;
                                            }
                                        };

                                        // Send via outgoing channel
                                        if outgoing_tx.send(json).await.is_err() {
                                            break;
                                        }
                                        continue;
                                    }

                                    // After handshake, update tick timestamp on tick events
                                    if handshake_completed && event.event == "tick" {
                                        let mut last = last_tick_task.lock().await;
                                        *last = Instant::now();
                                    }

                                    // Parse event payload into GatewayEvent for UI
                                    if handshake_completed {
                                        // Convert EventFrame to GatewayEvent by injecting type = event.event
                                        if let Some(payload_obj) = event.payload.as_ref().and_then(|v| v.as_object()) {
                                            let mut combined = payload_obj.clone();
                                            combined.insert("type".to_string(), serde_json::Value::String(event.event.clone()));
                                            if let Ok(json) = serde_json::to_string(&combined) {
                                                if let Some(gateway_event) = parse_gateway_event(&json) {
                                                    let gateway_msg = match gateway_event {
                                                        crate::ai::GatewayEvent::AgentTextDelta { session_id, delta } => {
                                                            Some(GatewayMessage::TextDelta { session_id, delta })
                                                        }
                                                        crate::ai::GatewayEvent::AgentTextDone { session_id } => {
                                                            Some(GatewayMessage::TextDone { session_id })
                                                        }
                                                        crate::ai::GatewayEvent::AgentRunComplete {
                                                            session_id,
                                                            result,
                                                            error,
                                                            ..
                                                        } => {
                                                            let (text, input_tokens, output_tokens) = result
                                                                .map(|r| {
                                                                    let t = r.payloads.first()
                                                                        .and_then(|p| p.text.clone())
                                                                        .unwrap_or_default();
                                                                    let (i, o) = r.meta
                                                                        .and_then(|m| m.usage)
                                                                        .map(|u| (u.input, u.output))
                                                                        .unwrap_or((0, 0));
                                                                    (t, i, o)
                                                                })
                                                                .unwrap_or_default();
                                                            Some(GatewayMessage::RunComplete {
                                                                session_id,
                                                                text,
                                                                input_tokens,
                                                                output_tokens,
                                                                error,
                                                            })
                                                        }
                                                        crate::ai::GatewayEvent::AgentUsage { input, output, .. } => {
                                                            Some(GatewayMessage::Usage { input, output })
                                                        }
                                                        crate::ai::GatewayEvent::Error { message, .. } => {
                                                            Some(GatewayMessage::Error(message))
                                                        }
                                                        _ => None,
                                                    };
                                                    if let Some(gm) = gateway_msg {
                                                        if incoming_tx_task.send(gm).await.is_err() {
                                                            break;
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                                // Try ResponseFrame
                                else if let Ok(resp) = serde_json::from_str::<ResponseFrame>(&text) {
                                    if !handshake_completed && resp.id == connect_req_id {
                                        // HelloOk response
                                        if resp.ok {
                                            if let Some(payload) = resp.payload {
                                                if let Ok(hello) = serde_json::from_value::<HelloOkPayload>(payload) {
                                                    // Store device token
                                                    *device_token_task.lock().await = Some(hello.auth.device_token);
                                                    // Store tick interval
                                                    *tick_interval_ms_task.lock().await = Some(hello.policy.tick_interval_ms);
                                                    // Initialize last_tick
                                                    *last_tick_task.lock().await = Instant::now();
                                                    // Mark handshake complete
                                                    handshake_completed = true;
                                                    // Signal success to connect()
                                                    let _ = handshake_tx.send(Ok(())).await;
                                                    continue;
                                                }
                                            }
                                        } else {
                                            let err_msg = resp.error.as_ref()
                                                .map(|e| format!("{}: {}", e.code, e.message))
                                                .unwrap_or_else(|| "Unknown error".to_string());
                                            let _ = handshake_tx.send(Err(anyhow::anyhow!(err_msg))).await;
                                            continue;
                                        }
                                    } else {
                                        // Normal RPC response - match pending requests
                                        let mut pending = pending_requests_task.lock().await;
                                        if let Some(tx) = pending.remove(&resp.id) {
                                            let result = if resp.ok {
                                                Ok(resp.payload.unwrap_or(serde_json::json!(null)))
                                            } else {
                                                let err_msg = resp.error.as_ref()
                                                    .map(|e| e.message.clone())
                                                    .unwrap_or_else(|| "Unknown error".to_string());
                                                Err(anyhow::anyhow!(err_msg))
                                            };
                                            let _ = tx.send(result).await;
                                        }
                                    }
                                } else {
                                    // Unknown message format
                                    eprintln!("Unknown message: {}", text);
                                }
                            }
                            Some(Ok(WsMessage::Close(_))) | None => {
                                let mut c = connected_task.lock().await;
                                *c = false;
                                let _ = incoming_tx_task.send(GatewayMessage::Disconnected).await;
                                break;
                            }
                            Some(Err(e)) => {
                                eprintln!("WebSocket error: {}", e);
                                let mut c = connected_task.lock().await;
                                *c = false;
                                let _ = incoming_tx_task.send(GatewayMessage::Disconnected).await;
                                break;
                            }
                            _ => {}
                        }
                    }
                }
            }
        });

        // Wait for handshake to complete or error
        match handshake_rx.recv().await {
            Some(Ok(_)) => {
                // Mark as connected on self
                *self.connected.lock().await = true;

                // Start tick watchdog using a clone of last_tick and connected
                let tick_ms = {
                    let t = self.tick_interval_ms.lock().await;
                    *t
                };
                if let Some(tick_interval) = tick_ms {
                    let tick_duration = Duration::from_millis(tick_interval * 2);
                    let connected_watchdog = self.connected.clone();
                    let last_tick_clone = self.last_tick.clone();
                    tokio::spawn(async move {
                        loop {
                            tokio::time::sleep(tick_duration).await;
                            let is_connected = *connected_watchdog.lock().await;
                            if !is_connected {
                                break;
                            }
                            let last = *last_tick_clone.lock().await;
                            if last.elapsed() >= tick_duration {
                                eprintln!("Tick timeout - disconnecting");
                                let mut c = connected_watchdog.lock().await;
                                *c = false;
                                break;
                            }
                        }
                    });
                }

                Ok(())
            }
            Some(Err(e)) => {
                // Handshake failed
                Err(e)
            }
            None => {
                Err(anyhow::anyhow!("Handshake task terminated unexpectedly"))
            }
        }
    }

    pub async fn reconnect(&mut self) -> Result<()> {
        self.close().await;
        tokio::time::sleep(Duration::from_millis(100)).await;
        self.connect().await
    }

    pub async fn send(&self, request: &crate::ai::AgentRequest) -> Result<()> {
        if let Some(sender) = &self.sender {
            // Build a RequestFrame for the "agent" method
            let req_frame = RequestFrame {
                frame_type: "req".to_string(),
                id: uuid::Uuid::new_v4().to_string(),
                method: "agent".to_string(),
                params: serde_json::to_value(request)?,
            };
            let json = serde_json::to_string(&req_frame)?;
            sender.send(json).await?;
        } else {
            return Err(anyhow::anyhow!("Not connected"));
        }
        Ok(())
    }

    pub async fn close(&mut self) {
        if let Some(tx) = &self.reconnect_tx {
            let _ = tx.send(()).await;
        }
        self.sender = None;
        self.receiver = None;
        self.reconnect_tx = None;
        let mut c = self.connected.lock().await;
        *c = false;
    }

    pub fn set_token(&mut self, token: Option<String>) {
        self.token = token;
    }
}

pub async fn start_reconnect_loop(
    gateway: Arc<Mutex<GatewayConnection>>,
    msg_tx: mpsc::Sender<GatewayMessage>,
) {
    let base_backoff = Duration::from_secs(5);
    let max_backoff = Duration::from_secs(60);
    let mut backoff = base_backoff;

    loop {
        tokio::time::sleep(backoff).await;

        let should_reconnect = {
            let g = gateway.lock().await;
            !g.is_connected().await
        };

        if should_reconnect {
            let _ = msg_tx.send(GatewayMessage::Reconnecting).await;

            let result = {
                let mut g = gateway.lock().await;
                g.reconnect().await
            };

            match result {
                Ok(_) => {
                    let _ = msg_tx.send(GatewayMessage::Connected).await;
                    backoff = base_backoff; // reset on success
                }
                Err(_) => {
                    let _ = msg_tx.send(GatewayMessage::Disconnected).await;
                    // exponential backoff with cap
                    backoff = (backoff * 2).min(max_backoff);
                }
            }
        } else {
            // Reset backoff if connected (in case it was increased earlier)
            backoff = base_backoff;
        }
    }
}

