                            if mods.is_empty() {
                                b.key.clone()
                            } else {
                                format!("{}+{}", mods, b.key)
                            }
                        })
                        .collect();
                    if !combos.is_empty() {
                        text.push_str(&format!("  {}: {}\n", action, combos.join(", ")));
                    }
                }
            }
            app.add_message("system", &text);
        }
        "/help" => {
            app.add_message(
                "system",
                "Available commands:\n\
                  /new, /reset    - Reset session\n\
                  /clear          - Clear chat\n\
                  /session [id]   - Show/switch session\n\
                  /sessions       - List recent sessions\n\
                  /history        - Load session history\n\
                  /agent [id]     - Show/set agent\n\
                  /model [name]   - Show/set model\n\
                  /think [level]  - Set thinking (off|minimal|low|medium|high|xhigh)\n\
                  /deliver        - Toggle deliver mode\n\
                  /verbose [on|off] - Toggle verbose\n\
                  /usage [mode]   - Set usage display (off|tokens|full)\n\
                  /cost           - Show session cost\n\
                  /timeout [sec]  - Set timeout\n\
                  /activation [m] - Set activation (mention|always)\n\
                  /restart        - Restart gateway\n\
                  /status         - Show session info\n\
                  /health         - Check gateway\n\
                  /compact        - Compact context\n\
                  /theme [name]   - Set/cycle theme\n\
                  /edit           - Edit last user message\n\
                  /regenerate     - Regenerate last response\n\
                  /multiline      - Toggle multi-line input\n\
                  /keybind <action> [combo] - View or set keybinding\n\
                  /unbind <action> - Remove keybinding\n\
                  /keybindings    - Show all keybindings\n\
                  /help           - Show this help",
            );
        }
        _ => {
            app.add_message(
                "system",
                &format!(
                    "Unknown command: {}. Type /help for available commands.",
                    cmd
                ),
            );
        }
    }
}

