    pub input_cursor: usize,
    pub input_mode: InputMode,
    pub messages: Vec<Message>,
    pub scroll_offset: usize,
    pub status_message: String,
    pub thinking_level: String,
    pub verbose: bool,
    pub tokens_used: u64,
    pub tokens_max: u64,
    pub session_id: String,
    pub agent_id: Option<String>,
    pub model: Option<String>,
    pub deliver: bool,
    pub timeout_seconds: Option<u32>,
    pub connection_status: ConnectionStatus,
    pub pending_message: Option<String>,
    pub pending_command: Option<String>,
    pub usage_mode: UsageMode,
    pub cost_usd: f64,
    pub activation_mode: String,
    pub theme: Theme,
    pub theme_name: String,
    pub error: Option<AppError>,
    pub editing_message: Option<usize>,
    pub message_counter: usize,
    pub keybindings: Keybindings,
    pub animation_tick: u64,
    pub showing_command_palette: bool,
    pub command_filter: String,
    pub command_selection: usize,
}

impl Default for App {
    fn default() -> Self {
        Self::from_saved(SavedState::default())
    }
}

impl App {
    pub fn from_saved(saved: SavedState) -> Self {
        let messages: Vec<Message> = saved.messages.into_iter().map(Message::from).collect();
        let keybindings = if saved.keybindings.is_empty() {
            default_keybindings()
        } else {
            saved.keybindings
        };
        Self {
            running: true,
            focus: Focus::Input,
            input: String::new(),
            input_cursor: 0,
            input_mode: InputMode::SingleLine,
            scroll_offset: 0,
            status_message: "Ready".to_string(),
            verbose: false,
            tokens_max: 200000,
            thinking_level: saved.thinking_level,
            tokens_used: saved.tokens_used,
            session_id: saved.session_id,
            messages,
            agent_id: None,
            model: None,
            deliver: false,
            timeout_seconds: None,
            connection_status: ConnectionStatus::Disconnected,
            pending_message: None,
            pending_command: None,
            usage_mode: UsageMode::Tokens,
            cost_usd: 0.0,
            activation_mode: "mention".to_string(),
            theme: Theme::default(),
            theme_name: "default".to_string(),
            error: None,
            editing_message: None,
            message_counter: 0,
            keybindings,
            animation_tick: 0,
            showing_command_palette: false,
            command_filter: String::new(),
            command_selection: 0,
        }
    }

    pub fn to_saved(&self) -> SavedState {
        SavedState {
            thinking_level: self.thinking_level.clone(),
            messages: self
                .messages
                .iter()
                .filter(|m| !m.streaming)
                .map(SavedMessage::from)
                .collect(),
            tokens_used: self.tokens_used,
            session_id: self.session_id.clone(),
            keybindings: self.keybindings.clone(),
        }
    }

    pub fn start_streaming_message(&mut self, role: &str) {
        self.message_counter += 1;
        self.messages.push(Message {
            role: role.to_string(),
            content: String::new(),
            streaming: true,
            input_tokens: 0,
            output_tokens: 0,
            cost: 0.0,
            timestamp: Instant::now(),
            id: self.message_counter,
        });
        self.scroll_to_bottom();
    }

    pub fn append_to_last_message(&mut self, delta: &str) {
        if let Some(last) = self.messages.last_mut() {
            last.content.push_str(delta);
        }
    }

    pub fn finish_streaming(&mut self) {
        if let Some(last) = self.messages.last_mut() {
            last.streaming = false;
        }
    }

    pub fn update_last_message_usage(&mut self, input: u64, output: u64, cost: f64) {
        if let Some(last) = self.messages.last_mut() {
            last.input_tokens = input;
            last.output_tokens = output;
            last.cost = cost;
        }
    }

    pub fn scroll_to_bottom(&mut self) {
        if !self.messages.is_empty() {
            self.scroll_offset = self.messages.len().saturating_sub(1);
        }
    }

    pub fn scroll_up(&mut self) {
        self.scroll_offset = self.scroll_offset.saturating_sub(1);
    }

    pub fn scroll_down(&mut self) {
        let max_offset = self.messages.len().saturating_sub(1);
        if self.scroll_offset < max_offset {
            self.scroll_offset += 1;
        }
    }

    pub fn cycle_focus(&mut self) {
        self.focus = match self.focus {
            Focus::Input => Focus::Chat,
            Focus::Chat => Focus::Input,
        };
    }

    pub fn token_percent(&self) -> f64 {
        if self.tokens_max == 0 {
            0.0
        } else {
            (self.tokens_used as f64 / self.tokens_max as f64) * 100.0
        }
    }

    pub fn connection_indicator(&self) -> (&'static str, ratatui::style::Color) {
        match &self.connection_status {
            ConnectionStatus::Connected => ("●", ratatui::style::Color::Green),
            ConnectionStatus::Connecting => ("◐", ratatui::style::Color::Yellow),
            ConnectionStatus::Disconnected => ("○", ratatui::style::Color::Gray),
        }
    }

    pub fn is_streaming(&self) -> bool {
        self.messages.last().map(|m| m.streaming).unwrap_or(false)
    }

    pub fn set_error(&mut self, message: &str) {
        self.error = Some(AppError {
            message: message.to_string(),
            timestamp: Instant::now(),
            is_warning: false,
        });
    }

    pub fn set_warning(&mut self, message: &str) {
        self.error = Some(AppError {
            message: message.to_string(),
            timestamp: Instant::now(),
            is_warning: true,
        });
    }

    pub fn clear_error(&mut self) {
        self.error = None;
    }

    pub fn toggle_input_mode(&mut self) {
        self.input_mode = match self.input_mode {
            InputMode::SingleLine => InputMode::MultiLine,
            InputMode::MultiLine => InputMode::SingleLine,
        };
    }

    pub fn cycle_theme(&mut self) {
        let (new_theme, name) = match self.theme_name.as_str() {
            "default" => (Theme::dark(), "dark"),
            "dark" => (Theme::light(), "light"),
            "light" => (Theme::monokai(), "monokai"),
            "monokai" => (Theme::dracula(), "dracula"),
            "dracula" | _ => (Theme::default(), "default"),
        };
        self.theme = new_theme;
        self.theme_name = name.to_string();
    }

    pub fn set_theme(&mut self, name: &str) {
        let theme = match name {
            "dark" => Theme::dark(),
            "light" => Theme::light(),
            "monokai" => Theme::monokai(),
            "dracula" => Theme::dracula(),
            _ => Theme::default(),
        };
        self.theme = theme;
        self.theme_name = name.to_string();
    }

    pub fn add_message(&mut self, role: &str, content: &str) {
        self.message_counter += 1;
        self.messages.push(Message {
            role: role.to_string(),
            content: content.to_string(),
            streaming: false,
            input_tokens: 0,
            output_tokens: 0,
            cost: 0.0,
            timestamp: Instant::now(),
            id: self.message_counter,
        });
        self.scroll_to_bottom();
    }

    pub fn insert_message_at(&mut self, index: usize, role: &str, content: &str) {
        self.message_counter += 1;
        self.messages.insert(
            index,
            Message {
                role: role.to_string(),
                content: content.to_string(),
                streaming: false,
                input_tokens: 0,
                output_tokens: 0,
                cost: 0.0,
                timestamp: Instant::now(),
                id: self.message_counter,
            },
        );
    }

    pub fn edit_message(&mut self, index: usize, new_content: &str) {
        if index < self.messages.len() {
            self.messages[index].content = new_content.to_string();
        }
    }

    pub fn delete_message(&mut self, index: usize) {
        if index < self.messages.len() {
            self.messages.remove(index);
        }
    }

    pub fn get_user_message_index(&mut self, direction: i32) -> Option<usize> {
        let current = self.editing_message.unwrap_or(self.messages.len());

        if direction > 0 {
            for (i, msg) in self.messages.iter().enumerate().skip(current + 1) {
                if msg.role == "user" {
                    return Some(i);
                }
            }
        } else {
            for (i, msg) in self.messages.iter().enumerate().rev().take(current) {
                if msg.role == "user" && i < current {
                    return Some(i);
                }
            }
        }
        None
    }

    pub fn start_editing(&mut self, index: usize) {
        if index < self.messages.len() && self.messages[index].role == "user" {
            self.editing_message = Some(index);
            self.input = self.messages[index].content.clone();
            self.input_cursor = self.input.len();
            self.focus = Focus::Input;
        }
    }

    pub fn cancel_editing(&mut self) {
        self.editing_message = None;
        self.input.clear();
        self.input_cursor = 0;
    }

    pub fn get_keybindings(&self, action: &str) -> Option<&Vec<Keybinding>> {
        self.keybindings.get(action)
    }

    pub fn set_keybinding(&mut self, action: String, modifiers: Vec<String>, key: String) {
        self.keybindings
            .insert(action, vec![Keybinding { modifiers, key }]);
    }

    pub fn add_keybinding(&mut self, action: String, modifiers: Vec<String>, key: String) {
        self.keybindings
            .entry(action)
            .or_insert_with(Vec::new)
            .push(Keybinding { modifiers, key });
    }

    pub fn remove_keybinding(&mut self, action: &str) -> bool {
        self.keybindings.remove(action).is_some()
    }

    pub fn list_keybindings(&self) -> Vec<(String, Vec<Keybinding>)> {
        let mut bindings: Vec<_> = self
            .keybindings
            .iter()
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect();
        bindings.sort_by_key(|(k, _)| k.clone());
        bindings
    }
}

