#[derive(Debug, Clone)]
pub struct Message {
    pub role: String,
    pub content: String,
    pub streaming: bool,
    pub input_tokens: u64,
    pub output_tokens: u64,
    pub cost: f64,
    #[allow(dead_code)]
    pub timestamp: Instant,
    pub id: usize,
}

impl From<SavedMessage> for Message {
    fn from(saved: SavedMessage) -> Self {
        Self {
            role: saved.role,
            content: saved.content,
            streaming: false,
            input_tokens: 0,
            output_tokens: 0,
            cost: 0.0,
            timestamp: Instant::now(),
            id: 0,
        }
    }
}

impl From<&Message> for SavedMessage {
    fn from(msg: &Message) -> Self {
        Self {
            role: msg.role.clone(),
            content: msg.content.clone(),
        }
    }
}

