impl Default for App {
    fn default() -> Self {
        Self::from_saved(SavedState::default())
    }
}

impl App {
    pub fn from_saved(saved: SavedState) -> Self {
        let messages: Vec<Message> = saved.messages.into_iter().map(Message::from).collect();
        let keybindings = if saved.keybindings.is_empty() {
            default_keybindings()
        } else {
            saved.keybindings
        };
        Self {
            running: true,
            focus: Focus::Input,
            input: String::new(),
            input_cursor: 0,
            input_mode: InputMode::SingleLine,
            scroll_offset: 0,
            status_message: "Ready".to_string(),
            verbose: false,
            tokens_max: 200000,
            thinking_level: saved.thinking_level,
            tokens_used: saved.tokens_used,
            session_id: saved.session_id,
            messages,
            agent_id: None,
            model: None,
            deliver: false,
            timeout_seconds: None,
            connection_status: ConnectionStatus::Disconnected,
            pending_message: None,
            pending_command: None,
            usage_mode: UsageMode::Tokens,
            cost_usd: 0.0,
            activation_mode: "mention".to_string(),
            theme: Theme::default(),
            theme_name: "default".to_string(),
            error: None,
            editing_message: None,
            message_counter: 0,
            keybindings,
            animation_tick: 0,
            showing_command_palette: false,
            command_filter: String::new(),
            command_selection: 0,
            showing_token_input: false,
            token_input: String::new(),
            token_cursor: 0,
            token_error: None,
            gateway_token: saved.gateway_token,
            token_needs_sync: false,
        }
    }

    pub fn to_saved(&self) -> SavedState {
        SavedState {
            thinking_level: self.thinking_level.clone(),
            messages: self
                .messages
                .iter()
                .filter(|m| !m.streaming)
                .map(SavedMessage::from)
                .collect(),
            tokens_used: self.tokens_used,
            session_id: self.session_id.clone(),
            keybindings: self.keybindings.clone(),
            gateway_token: self.gateway_token.clone(),
        }
    }

    pub fn start_streaming_message(&mut self, role: &str) {
        self.message_counter += 1;
        self.messages.push(Message {
            role: role.to_string(),
            content: String::new(),
            streaming: true,
            input_tokens: 0,
            output_tokens: 0,
            cost: 0.0,
            timestamp: Instant::now(),
            id: self.message_counter,
        });
        self.scroll_to_bottom();
    }

    pub fn append_to_last_message(&mut self, delta: &str) {
        if let Some(last) = self.messages.last_mut() {
            last.content.push_str(delta);
        }
    }

    pub fn finish_streaming(&mut self) {
        if let Some(last) = self.messages.last_mut() {
            last.streaming = false;
        }
    }

    pub fn update_last_message_usage(&mut self, input: u64, output: u64, cost: f64) {
        if let Some(last) = self.messages.last_mut() {
            last.input_tokens = input;
            last.output_tokens = output;
            last.cost = cost;
        }
    }

    pub fn scroll_to_bottom(&mut self) {
        if !self.messages.is_empty() {
            self.scroll_offset = self.messages.len().saturating_sub(1);
        }
    }

    pub fn scroll_up(&mut self) {
        self.scroll_offset = self.scroll_offset.saturating_sub(1);
    }

    pub fn scroll_down(&mut self) {
        let max_offset = self.messages.len().saturating_sub(1);
        if self.scroll_offset < max_offset {
            self.scroll_offset += 1;
        }
    }

    pub fn cycle_focus(&mut self) {
        self.focus = match self.focus {
            Focus::Input => Focus::Chat,
            Focus::Chat => Focus::Input,
        };
    }

    pub fn token_percent(&self) -> f64 {
        if self.tokens_max == 0 {
            0.0
        } else {
            (self.tokens_used as f64 / self.tokens_max as f64) * 100.0
        }
    }

    pub fn connection_indicator(&self) -> (&'static str, ratatui::style::Color) {
        match &self.connection_status {
            ConnectionStatus::Connected => ("●", ratatui::style::Color::Green),
            ConnectionStatus::Connecting => ("◐", ratatui::style::Color::Yellow),
            ConnectionStatus::Disconnected => ("○", ratatui::style::Color::Gray),
        }
    }

    pub fn is_streaming(&self) -> bool {
        self.messages.last().map(|m| m.streaming).unwrap_or(false)
    }

    pub fn set_error(&mut self, message: &str) {
        self.error = Some(AppError {
            message: message.to_string(),
            timestamp: Instant::now(),
            is_warning: false,
        });
    }

    pub fn set_warning(&mut self, message: &str) {
        self.error = Some(AppError {
            message: message.to_string(),
            timestamp: Instant::now(),
            is_warning: true,
        });
    }

    pub fn clear_error(&mut self) {
        self.error = None;
    }

    pub fn toggle_input_mode(&mut self) {
        self.input_mode = match self.input_mode {
            InputMode::SingleLine => InputMode::MultiLine,
            InputMode::MultiLine => InputMode::SingleLine,
        };
    }

    pub fn cycle_theme(&mut self) {
        let (new_theme, name) = match self.theme_name.as_str() {
            "default" => (Theme::dark(), "dark"),
            "dark" => (Theme::light(), "light"),
            "light" => (Theme::monokai(), "monokai"),
            "monokai" => (Theme::dracula(), "dracula"),
            "dracula" | _ => (Theme::default(), "default"),
        };
        self.theme = new_theme;
        self.theme_name = name.to_string();
    }

    pub fn set_theme(&mut self, name: &str) {
        let theme = match name {
            "dark" => Theme::dark(),
            "light" => Theme::light(),
            "monokai" => Theme::monokai(),
            "dracula" => Theme::dracula(),
            _ => Theme::default(),
        };
        self.theme = theme;
        self.theme_name = name.to_string();
    }

    pub fn add_message(&mut self, role: &str, content: &str) {
        self.message_counter += 1;
        self.messages.push(Message {
            role: role.to_string(),
            content: content.to_string(),
            streaming: false,
            input_tokens: 0,
            output_tokens: 0,
            cost: 0.0,
            timestamp: Instant::now(),
            id: self.message_counter,
        });
        self.scroll_to_bottom();
    }

    pub fn insert_message_at(&mut self, index: usize, role: &str, content: &str) {
        self.message_counter += 1;
        self.messages.insert(
            index,
            Message {
                role: role.to_string(),
                content: content.to_string(),
                streaming: false,
                input_tokens: 0,
                output_tokens: 0,
                cost: 0.0,
                timestamp: Instant::now(),
                id: self.message_counter,
            },
        );
    }

    pub fn edit_message(&mut self, index: usize, new_content: &str) {
        if index < self.messages.len() {
            self.messages[index].content = new_content.to_string();
        }
    }

    pub fn delete_message(&mut self, index: usize) {
        if index < self.messages.len() {
            self.messages.remove(index);
        }
    }

    pub fn get_user_message_index(&mut self, direction: i32) -> Option<usize> {
        let current = self.editing_message.unwrap_or(self.messages.len());

        if direction > 0 {
            for (i, msg) in self.messages.iter().enumerate().skip(current + 1) {
                if msg.role == "user" {
                    return Some(i);
                }
            }
        } else {
            for (i, msg) in self.messages.iter().enumerate().rev().take(current) {
                if msg.role == "user" && i < current {
                    return Some(i);
                }
            }
        }
        None
    }

    pub fn start_editing(&mut self, index: usize) {
        if index < self.messages.len() && self.messages[index].role == "user" {
            self.editing_message = Some(index);
            self.input = self.messages[index].content.clone();
            self.input_cursor = self.input.len();
            self.focus = Focus::Input;
        }
    }

    pub fn cancel_editing(&mut self) {
        self.editing_message = None;
        self.input.clear();
        self.input_cursor = 0;
    }

    pub fn get_keybindings(&self, action: &str) -> Option<&Vec<Keybinding>> {
        self.keybindings.get(action)
    }

    pub fn set_keybinding(&mut self, action: String, modifiers: Vec<String>, key: String) {
        self.keybindings
            .insert(action, vec![Keybinding { modifiers, key }]);
    }

    pub fn add_keybinding(&mut self, action: String, modifiers: Vec<String>, key: String) {
        self.keybindings
            .entry(action)
            .or_insert_with(Vec::new)
            .push(Keybinding { modifiers, key });
    }

    pub fn remove_keybinding(&mut self, action: &str) -> bool {
        self.keybindings.remove(action).is_some()
    }

    pub fn list_keybindings(&self) -> Vec<(String, Vec<Keybinding>)> {
        let mut bindings: Vec<_> = self
            .keybindings
            .iter()
            .map(|(k, v)| (k.clone(), v.clone()))
            .collect();
        bindings.sort_by_key(|(k, _)| k.clone());
        bindings
    }
}

before:
mod ai;
mod app;
mod persistence;
mod ui;

use std::sync::Arc;
use std::sync::Mutex as StdMutex;
use std::time::Duration;

use ai::{AgentRequest, GatewayConnection, GatewayMessage};
use app::App;
use crossterm::event::{self, Event};
use persistence::{load_state, save_state};
use ratatui::Terminal;
use tokio::sync::mpsc;
use tokio::sync::Mutex as TokioMutex;

fn main() -> anyhow::Result<()> {
    let saved = load_state();
    let app_state = App::from_saved(saved);
    let app = Arc::new(StdMutex::new(app_state));

    let rt = tokio::runtime::Runtime::new()?;
    rt.block_on(async {
        let (msg_tx, mut msg_rx) = mpsc::channel::<GatewayMessage>(64);

        let mut gateway_conn = GatewayConnection::new("ws://127.0.0.1:18789");

        {
            let mut app_guard = app.lock().unwrap();
            app_guard.connection_status = app::ConnectionStatus::Connecting;
            app_guard.status_message = "Connecting...".to_string();
        }

        match gateway_conn.connect().await {
            Ok(_) => {
                let mut app_guard = app.lock().unwrap();
                app_guard.connection_status = app::ConnectionStatus::Connected;
                app_guard.status_message = "Connected".to_string();
            }
            Err(_) => {
                let mut app_guard = app.lock().unwrap();
                app_guard.connection_status = app::ConnectionStatus::Disconnected;
                app_guard.status_message = "Gateway offline - will retry".to_string();
            }
        }

        let gateway = Arc::new(TokioMutex::new(gateway_conn));
        let gateway_clone = gateway.clone();
        let msg_tx_clone = msg_tx.clone();

        tokio::spawn(async move {
            let mut receiver = {
                let mut g = gateway_clone.lock().await;
                g.take_receiver()
            };

            if let Some(rx) = &mut receiver {
                while let Some(msg) = rx.recv().await {
                    if msg_tx_clone.send(msg).await.is_err() {
                        break;
                    }
                }
            }
        });

        let gateway_reconnect = gateway.clone();
        let msg_tx_reconnect = msg_tx.clone();
        tokio::spawn(async move {
            ai::start_reconnect_loop(gateway_reconnect, msg_tx_reconnect).await;
        });

        let mut terminal = ratatui::init();

        let result = run_app(&mut terminal, app.clone(), gateway, &mut msg_rx).await;

        let saved_state = {
            let app_guard = app.lock().unwrap();
            app_guard.to_saved()
        };
        if let Err(e) = save_state(&saved_state) {
            eprintln!("Failed to save state: {}", e);
        }

        ratatui::restore();
        result
    })
}

async fn run_app(
    terminal: &mut Terminal<ratatui::backend::CrosstermBackend<std::io::Stdout>>,
    app: Arc<StdMutex<App>>,
    gateway: Arc<TokioMutex<GatewayConnection>>,
    msg_rx: &mut mpsc::Receiver<GatewayMessage>,
) -> anyhow::Result<()> {
    loop {
        {
            let app_guard = app.lock().unwrap();
            terminal.draw(|frame| ui::render(frame, &app_guard))?;
        }

        if event::poll(Duration::from_millis(16))? {
            match event::read()? {
                Event::Key(key) => {
                    let mut app_guard = app.lock().unwrap();
                    app::handle_events(&mut app_guard, Event::Key(key))?;
                }
                Event::Resize(_, _) => {}
                _ => {}
            }
        }

        while let Ok(msg) = msg_rx.try_recv() {
            let mut app_guard = app.lock().unwrap();
            match msg {
                GatewayMessage::TextDelta { delta, .. } => {
                    app_guard.append_to_last_message(&delta);
                }
                GatewayMessage::TextDone { .. } => {
                    app_guard.finish_streaming();
                    app_guard.status_message = "Ready".to_string();
                }
                GatewayMessage::RunComplete {
                    text,
                    input_tokens,
                    output_tokens,
                    error,
                    ..
                } => {
                    let cost = estimate_cost(&text, input_tokens, output_tokens);

                    if app_guard.is_streaming() {
                        if let Some(last) = app_guard.messages.last_mut() {
                            last.content = text;
                            last.streaming = false;
                            last.input_tokens = input_tokens;
                            last.output_tokens = output_tokens;
                            last.cost = cost;
                        }
                    } else {
                        app_guard.add_message("assistant", &text);
                        app_guard.update_last_message_usage(input_tokens, output_tokens, cost);
                    }
                    app_guard.tokens_used += input_tokens + output_tokens;
                    app_guard.cost_usd += cost;
                    if let Some(e) = error {
                        app_guard.status_message = format!("Error: {}", e);
                    } else {
                        app_guard.status_message = "Ready".to_string();
                    }
                }
                GatewayMessage::Usage { input, output } => {
                    app_guard.tokens_used += input + output;
                }
                GatewayMessage::Connected => {
                    app_guard.connection_status = app::ConnectionStatus::Connected;
                    app_guard.status_message = "Connected".to_string();
                    app_guard.clear_error();
                }
                GatewayMessage::Disconnected => {
                    app_guard.connection_status = app::ConnectionStatus::Disconnected;
                    app_guard.status_message = "Disconnected - retrying...".to_string();
                }
                GatewayMessage::Reconnecting => {
                    app_guard.connection_status = app::ConnectionStatus::Connecting;
                    app_guard.status_message = "Reconnecting...".to_string();
                }
                GatewayMessage::Error(e) => {
                    app_guard.set_error(&format!("Error: {}", e));
                    app_guard.status_message = "Error".to_string();
                }
            }
        }

        // Increment animation tick each frame
        {
            let mut app_guard = app.lock().unwrap();
            app_guard.animation_tick += 1;
        }


        let (pending_msg, pending_cmd) = {
            let mut app_guard = app.lock().unwrap();
            let msg = app_guard.pending_message.take();
            let cmd = app_guard.pending_command.take();
            (msg, cmd)
        };

        if let Some(message) = pending_msg {
            let (session_id, thinking, agent, model, deliver, verbose, timeout, is_connected) = {
                let app_guard = app.lock().unwrap();
                (
                    app_guard.session_id.clone(),
                    app_guard.thinking_level.clone(),
                    app_guard.agent_id.clone(),
                    app_guard.model.clone(),
                    app_guard.deliver,
                    app_guard.verbose,
                    app_guard.timeout_seconds,
                    app_guard.connection_status == app::ConnectionStatus::Connected,
                )
            };

            if is_connected {
                let mut app_guard = app.lock().unwrap();
                app_guard.add_message("user", &message);
                app_guard.start_streaming_message("assistant");
                app_guard.status_message = "Streaming...".to_string();

                let req = build_agent_request(&session_id, &message, &thinking, agent.as_deref(), model.as_deref(), deliver, verbose, timeout);

                let g = gateway.lock().await;
                let _ = g.send(&req).await;
            } else {
                let mut app_guard = app.lock().unwrap();
                app_guard.add_message("system", "Not connected to gateway. Cannot send message.");
            }
        }

        if let Some(cmd) = pending_cmd {
            handle_special_command(&app, &gateway, &cmd).await;
        }

        {
            let app_guard = app.lock().unwrap();
            if !app_guard.running {
                break;
            }
        }
    }

    Ok(())
}

fn build_agent_request(
    session_id: &str,
    message: &str,
    thinking: &str,
    agent: Option<&str>,
    model: Option<&str>,
    deliver: bool,
    verbose: bool,
    timeout: Option<u32>,
) -> AgentRequest {
    let mut req = AgentRequest::new(session_id, message);

    if let Some(a) = agent {
        req = req.with_agent(a);
    }
    if let Some(m) = model {
        req = req.with_model(m);
    }

    req = req.with_thinking(thinking);

    if deliver {
        req = req.with_deliver(true);
    }
    if verbose {
        req = req.with_verbose(true);
    }
    if let Some(t) = timeout {
        req = req.with_timeout(t);
    }

    req
}

async fn handle_special_command(
    app: &Arc<StdMutex<App>>,
    gateway: &Arc<TokioMutex<GatewayConnection>>,
    cmd: &str,
) {
    match cmd {
        "/restart" => {
            let result = std::process::Command::new("openclaw")
                .args(["gateway", "restart"])
                .output();

            let mut app_guard = app.lock().unwrap();
            match result {
                Ok(output) => {
                    if output.status.success() {
                        app_guard.add_message("system", "Gateway restart initiated.");
                        app_guard.status_message = "Restarting...".to_string();
                    } else {
                        let stderr = String::from_utf8_lossy(&output.stderr);
                        app_guard.add_message("system", &format!("Restart failed: {}", stderr));
                    }
                }
                Err(e) => {
                    app_guard.add_message("system", &format!("Failed to restart: {}", e));
                }
            }
        }
        "/compact" => {
            let session_id = {
                let app_guard = app.lock().unwrap();
                app_guard.session_id.clone()
            };

            let req = AgentRequest::new(&session_id, "/compact");
            let g = gateway.lock().await;
            let _ = g.send(&req).await;
        }
