fn render_error_popup(frame: &mut Frame, app: &App, message: String, is_warning: bool) {
    let area = frame.area();
    let popup_area = Rect {
        x: area.width.saturating_sub(60) / 2,
        y: area.height.saturating_sub(5) / 2,
        width: 60.min(area.width.saturating_sub(4)),
        height: 5.min(area.height.saturating_sub(4)),
    };

    let color = if is_warning {
        app.theme.system_color
    } else {
        app.theme.error_color
    };

    let block = Block::default()
        .title(if is_warning { " Warning " } else { " Error " })
        .borders(Borders::ALL)
        .border_style(Style::default().fg(color));

    let paragraph = Paragraph::new(message)
        .block(block)
        .style(Style::default().fg(color));

    frame.render_widget(paragraph, popup_area);
}

fn render_header(frame: &mut Frame, app: &App, area: Rect) {
