            format!("agent:{} ", a),
            Style::default().fg(app.theme.muted_color),
        )
    } else {
        Span::raw("")
    };

    let deliver = if app.deliver {
        Span::styled(
            "DELIVER ",
            Style::default().fg(app.theme.error_color).bold(),
        )
    } else {
        Span::raw("")
    };

    let theme_tag = Span::styled(
        format!("[{}] ", app.theme_name),
        Style::default().fg(app.theme.accent_color),
    );

    let mode_tag = match app.input_mode {
        crate::app::InputMode::MultiLine => {
            Span::styled("[ML] ", Style::default().fg(app.theme.system_color))
        }
        _ => Span::raw(""),
    };

    let status = Span::styled(
        format!("| {} ", app.status_message),
        Style::default().fg(app.theme.muted_color),
    );

    let help = Span::styled(
        "Ctrl+N:Switch | Ctrl+T:Theme | /help",
        Style::default().fg(app.theme.divider_color),
    );

    let paragraph = Paragraph::new(vec![ratatui::text::Line::from(vec![
        conn, title, session, model, agent, deliver, theme_tag, mode_tag, status, help,
    ])]);
    frame.render_widget(paragraph, area);
}

fn render_status_bar(frame: &mut Frame, app: &App, area: Rect) {
    let tokens = Span::styled(
        format!("Tokens: {}/{}", app.tokens_used, app.tokens_max),
        Style::default().fg(app.theme.accent_color),
    );

    let percent = app.token_percent();
    let percent_color = if percent > 80.0 {
        app.theme.error_color
    } else if percent > 50.0 {
        app.theme.system_color
    } else {
        app.theme.user_color
    };
    let percent_span = Span::styled(
        format!(" ({:.1}%)", percent),
        Style::default().fg(percent_color),
    );

    let separator = Span::styled(" │ ", Style::default().fg(app.theme.divider_color));

    let thinking = Span::styled(
        format!("Think: {}", app.thinking_level),
        Style::default().fg(app.theme.system_color),
    );

    let verbose = if app.verbose {
        Span::styled(" VERBOSE", Style::default().fg(app.theme.system_color))
    } else {
        Span::raw("")
    };

    let cost = if app.cost_usd > 0.0 {
        Span::styled(
            format!(" │ ${:.4}", app.cost_usd),
            Style::default().fg(app.theme.user_color),
        )
    } else {
        Span::raw("")
    };

    let timeout = if let Some(t) = app.timeout_seconds {
        Span::styled(
            format!(" │ Timeout: {}s", t),
            Style::default().fg(app.theme.muted_color),
        )
    } else {
        Span::raw("")
    };

    let paragraph = Paragraph::new(vec![ratatui::text::Line::from(vec![
        tokens,
        percent_span,
        separator,
        thinking,
        verbose,
        cost,
        timeout,
    ])]);
    frame.render_widget(paragraph, area);
}

fn render_command_palette(frame: &mut Frame, app: &App, anchor: Rect, cursor_x: u16) {
    let area = frame.area();

    // Get filtered commands
    let commands = {
        let filter = &app.command_filter;
        if filter.is_empty() || filter == "/" {
            crate::app::COMMANDS.to_vec()
        } else {
            crate::app::COMMANDS
                .iter()
                .filter(|(cmd, _)| cmd.starts_with(filter))
                .copied()
                .collect()
        }
    };

    if commands.is_empty() {
        return;
    }

    // Determine dimensions
    let max_width = 60u16.min(area.width.saturating_sub(4));
    let max_height = 15u16.min(area.height.saturating_sub(4));

    // Calculate needed width and height
    let title_len = "Commands".len() as u16;
    let max_cmd_desc_len = commands
        .iter()
        .map(|(cmd, desc)| cmd.len() + 2 + desc.len())
        .max()
        .unwrap_or(0) as u16;
    let needed_width = (title_len.max(max_cmd_desc_len) + 4) as u16; // padding
    let needed_height = (commands.len() + 2) as u16; // title + commands + border

    let width = needed_width
        .min(max_width)
        .min(area.width.saturating_sub(4));
    let height = needed_height
        .min(max_height)
        .min(area.height.saturating_sub(4));

    // Position above cursor (left-aligned with cursor), ensuring it stays on screen
    let mut x = anchor.x + cursor_x.saturating_sub(width / 2);
    if x + width > area.width {
        x = area.width.saturating_sub(width);
    }
    if x < anchor.x {
        x = anchor.x;
    }
    let y = anchor.y.saturating_sub(height);

    let popup_area = Rect {
        x,
        y,
        width,
        height,
    };

    let title = Span::styled(
        " Commands ",
        Style::default().fg(app.theme.accent_color).bold(),
    );

    let block = Block::default()
        .title(title)
        .borders(Borders::ALL)
        .border_style(Style::default().fg(app.theme.border_color));

    let inner = block.inner(popup_area);
    frame.render_widget(block, popup_area);

    // Render commands list
    for (i, (cmd, desc)) in commands.iter().enumerate() {
        if i >= inner.height as usize {
            break;
        }
        let line_y = inner.y + i as u16;
        let is_selected = i == app.command_selection;

        let line = ratatui::text::Line::from(vec![
            Span::raw("  "),
            Span::styled(
                *cmd,
                Style::default()
                    .fg(if is_selected {
                        app.theme.accent_color
                    } else {
                        app.theme.user_color
                    })
                    .bold(),
            ),
            Span::raw(" - "),
            Span::styled(
                *desc,
                Style::default().fg(if is_selected {
                    app.theme.accent_color
                } else {
                    app.theme.muted_color
                }),
            ),
        ]);

        frame.render_widget(
            Paragraph::new(line),
            Rect {
                x: inner.x,
                y: line_y,
                width: inner.width,
                height: 1,
            },
        );
    }
}

fn render_token_modal(frame: &mut Frame, app: &App, area: Rect) {
    // Determine dimensions
    let width = 60u16.min(area.width.saturating_sub(4));
    let height = 7u16.min(area.height.saturating_sub(4));

    // Center the modal
    let x = area.x + (area.width - width) / 2;
    let y = area.y + (area.height - height) / 2;

    let modal_area = Rect {
        x,
        y,
        width,
        height,
    };

    // Render background
    let block = Block::default()
        .title(Span::styled(
            " Gateway Token ",
            Style::default().fg(app.theme.accent_color).bold(),
        ))
        .borders(Borders::ALL)
        .border_style(Style::default().fg(app.theme.border_color))
        .style(Style::default().bg(app.theme.muted_color));

    let inner = block.inner(modal_area);
    frame.render_widget(block, modal_area);

    // Instruction text
    let instruction = ratatui::text::Line::from(Span::raw("Enter your OpenClaw gateway token:"));
    frame.render_widget(
        Paragraph::new(instruction),
        Rect {
            x: inner.x,
            y: inner.y,
            width: inner.width,
            height: 1,
        },
    );

    // Token input field (masked with asterisks)
    let masked_input = "*".repeat(app.token_input.len());
    let cursor_pos = if app.token_cursor < masked_input.len() {
        app.token_cursor as u16
    } else {
        masked_input.len() as u16
    };

    let input_line = ratatui::text::Line::from(Span::raw(masked_input));
    let input_area = Rect {
        x: inner.x,
        y: inner.y + 1,
        width: inner.width,
        height: 1,
    };
    frame.render_widget(Paragraph::new(input_line), input_area);

    // Render cursor position (simple block cursor)
    if app.showing_token_input {
        let cursor_x = input_area.x + cursor_pos;
        if cursor_x < input_area.x + input_area.width {
            frame.render_widget(
                Paragraph::new(Span::styled(
                    " ",
                    Style::default()
                        .fg(app.theme.accent_color)
                        .bg(app.theme.accent_color),
                )),
                Rect {
                    x: cursor_x,
                    y: input_area.y,
                    width: 1,
                    height: 1,
                },
            );
        }
    }

    // Error message if any
    if let Some(ref err) = app.token_error {
        let error_line = ratatui::text::Line::from(Span::styled(
            err,
            Style::default().fg(app.theme.error_color),
        ));
        frame.render_widget(
            Paragraph::new(error_line),
            Rect {
                x: inner.x,
                y: inner.y + 2,
                width: inner.width,
                height: 1,
            },
        );
    }

    // Help text
    let help_line = ratatui::text::Line::from(Span::raw("Press Enter to save, Esc to cancel"));
    frame.render_widget(
        Paragraph::new(help_line),
        Rect {
            x: inner.x,
            y: inner.y + 3,
            width: inner.width,
            height: 1,
        },
    );
}
